    {% set dispatch_url = base_url + '/app/dispatch?delivery_note=' + doc.name %}

    <!-- QR Code with Reduced Size -->
    <img src="https://api.qrserver.com/v1/create-qr-code/?data={{ dispatch_url | urlencode }}&size=150x150&margin=1&format=png&qzone=1"
        alt="QR Code"
        style="width: 80px; height: 80px; display: block; margin: 0 auto; border: 1px solid #ccc;">

    <!-- Status Inline with QR Code -->
    {% if doc.custom_dispatch_status == 'Dispatched' %}
    <div style="
        background-color: #4CAF50;
        color: white;
        font-size: 10px;
        font-weight: bold;
        padding: 2px 6px;
        border-radius: 4px;
        margin-top: 4px;
        display: inline-block;
    ">
        ✓ Dispatched
    </div>
    {% else %}
    <div style="
        background-color: #FFC107;
        color: black;
        font-size: 10px;
        font-weight: bold;
        padding: 2px 6px;
        border-radius: 4px;
        margin-top: 4px;
        display: inline-block;
    ">
        Pending
    </div>
    {% endif %}
</td>
