            <table class = "table table-sm; " style = "width:100%; margin-top:-1px !important;" cellspacing = '0' cellpadding = '0'> 
                <tr>
                    <td style = 'font-size:11px'> PO Date: </td> <td style = 'font-size:11px'>   {{ frappe.utils.formatdate(doc.get_formatted(frappe.db.get_value('Purchase Order', doc.po_no, 'transaction_date')), "dd-mm-yyyy") }}</td>
                </tr>
                <tr>
                    <td style = 'font-size:11px'> Customer PO#. </td> <td style = 'font-size:11px'>  {{doc.po_no }} </td>
                </tr>
          
                <tr>
                    <td style = 'font-size:11px'> Sales Person: </td> <td style = 'font-size:11px'>{% if doc.sales_team[0] %}{{doc.sales_team[0].sales_person}}{% endif %}</td>
                </tr>
                {% if doc.is_return == 1 %}
                <tr>
                    <td style = 'font-size:11px'> Return Against: </td> <td style = 'font-size:11px'>  {{doc.return_against }} </td>
                </tr>
                {% endif %}
            </table>
        </td>
    </tr>
</table>
<table style="width: 98%; border: 0px solid white !important; margin-top: 0px;">
